let safeSpaceBreathInterval = null;
let safeSpaceBreathTimeout = null;
let safeSpaceBreathStep = 0;
let currentBreathPattern = '444'; // '444', '478', 'sigh'
let safeSpaceNoiseActive = false;
let anchorStep = 1;
let eyeRestTimerInterval = null;
let eyeRestSeconds = 20;
let eyeRestRunning = false;
let dopamineDetoxInterval = null;
let dopamineDetoxSeconds = 60;

window.openBreakModal = function(type, pattern) {
  if (type === 'stretch') {
    if (typeof openSportModal === 'function') {
      openSportModal();
      return;
    }
  }
  openSafeSpaceModal();
  if (pattern) {
    currentBreathPattern = pattern;
  }
  if (type === 'grounding') {
    switchSafeSpaceTab('anchor');
  } else if (type === 'eyes') {
    switchSafeSpaceTab('eyes');
  } else if (type === 'body') {
    switchSafeSpaceTab('body');
  } else if (type === 'sound') {
    switchSafeSpaceTab('sound');
  } else {
    switchSafeSpaceTab('breath');
  }
};

function openSafeSpaceModal() {
  const modal = document.getElementById('helper-safespace-modal');
  if (modal) modal.classList.remove('hidden');
  switchSafeSpaceTab('breath');
}
window.openSafeSpaceModal = openSafeSpaceModal;

function closeSafeSpaceModal() {
  const modal = document.getElementById('helper-safespace-modal');
  if (modal) modal.classList.add('hidden');
  stopSafeSpaceBreathCycle();
  stopEyeRestTimer();
  if (dopamineDetoxInterval) {
    clearInterval(dopamineDetoxInterval);
    dopamineDetoxInterval = null;
  }
  if (safeSpaceNoiseActive) {
    toggleSafeSpaceNoise();
  }
}
window.closeSafeSpaceModal = closeSafeSpaceModal;

function switchPauseDropdownTab(tabName) {
  ['breath', 'sensory', 'body', 'sound'].forEach(t => {
    const pane = document.getElementById(`pause-dropdown-pane-${t}`);
    const tabBtn = document.getElementById(`pause-dropdown-tab-${t}`);
    if (pane) {
      if (t === tabName) pane.classList.remove('hidden');
      else pane.classList.add('hidden');
    }
    if (tabBtn) {
      if (t === tabName) {
        tabBtn.className = "py-1.5 px-2 rounded-xl bg-teal-500/20 text-teal-200 border border-teal-500/40 font-bold transition text-center cursor-pointer";
      } else {
        tabBtn.className = "py-1.5 px-2 rounded-xl text-gray-400 hover:text-white hover:bg-white/5 transition text-center cursor-pointer";
      }
    }
  });
}
window.switchPauseDropdownTab = switchPauseDropdownTab;

function switchSafeSpaceTab(tab) {
  const tabs = ['breath', 'anchor', 'eyes', 'body', 'sound'];
  tabs.forEach(t => {
    const btn = document.getElementById(`safespace-tab-${t}`);
    const pane = document.getElementById(`safespace-pane-${t}`);
    if (pane) {
      if (t === tab) pane.classList.remove('hidden');
      else pane.classList.add('hidden');
    }
    if (btn) {
      if (t === tab) {
        btn.className = "py-2 px-2 rounded-xl transition cursor-pointer flex items-center justify-center gap-1.5 text-teal-300 bg-teal-500/20 border border-teal-500/40 font-bold shadow-sm";
      } else {
        btn.className = "py-2 px-2 rounded-xl transition cursor-pointer flex items-center justify-center gap-1.5 text-gray-400 hover:text-white hover:bg-white/5";
      }
    }
  });

  stopSafeSpaceBreathCycle();
  stopEyeRestTimer();

  if (tab === 'breath') {
    startSafeSpaceBreathCycle();
  } else if (tab === 'anchor') {
    resetAnchorSteps();
  } else if (tab === 'eyes') {
    resetEyeRestUI();
  }
}
window.switchSafeSpaceTab = switchSafeSpaceTab;

function setBreathPattern(pat) {
  currentBreathPattern = pat;
  ['444', '478', 'sigh'].forEach(p => {
    const btn = document.getElementById(`safespace-pat-${p}`);
    if (btn) {
      if (p === pat) {
        btn.className = "py-1 px-2.5 rounded-lg bg-teal-500/30 text-teal-200 border border-teal-400 font-bold text-xs transition cursor-pointer";
      } else {
        btn.className = "py-1 px-2.5 rounded-lg bg-white/5 text-gray-400 hover:text-white border border-white/10 text-xs transition cursor-pointer";
      }
    }
  });
  startSafeSpaceBreathCycle();
}
window.setBreathPattern = setBreathPattern;

function startSafeSpaceBreathCycle() {
  stopSafeSpaceBreathCycle();
  const circle = document.getElementById('safespace-breath-circle');
  const text = document.getElementById('safespace-breath-text');
  const countEl = document.getElementById('safespace-breath-count');
  if (!circle || !text) return;

  if (currentBreathPattern === '478') {
    // 4-7-8 Breathing (4s Inhale, 7s Hold, 8s Exhale)
    const run478 = () => {
      text.innerText = tr({ de: "Einatmen (Nase)", en: "Inhale (Nose)", fr: "Inspirez (Nez)", it: "Inspira (Naso)", es: "Inhala (Nariz)", el: "Εισπνοή (Μύτη)" });
      if (countEl) countEl.innerText = "4s";
      circle.style.transform = "scale(1.4)";
      circle.style.borderColor = "rgba(20, 184, 166, 0.9)";
      circle.style.backgroundColor = "rgba(20, 184, 166, 0.18)";

      safeSpaceBreathTimeout = setTimeout(() => {
        text.innerText = tr({ de: "Anhalten (Sanft)", en: "Hold (Gently)", fr: "Bloquez (Doux)", it: "Trattieni (Dolce)", es: "Mantén (Suave)", el: "Κράτημα (Απαλά)" });
        if (countEl) countEl.innerText = "7s";
        circle.style.borderColor = "rgba(245, 158, 11, 0.8)";
        circle.style.backgroundColor = "rgba(245, 158, 11, 0.15)";

        safeSpaceBreathTimeout = setTimeout(() => {
          text.innerText = tr({ de: "Langsam Ausatmen (Mund)", en: "Slow Exhale (Mouth)", fr: "Expirez lentement (Bouche)", it: "Espira lentamente (Bocca)", es: "Exhala lento (Boca)", el: "Εκπνοή αργά (Στόμα)" });
          if (countEl) countEl.innerText = "8s";
          circle.style.transform = "scale(0.9)";
          circle.style.borderColor = "rgba(99, 102, 241, 0.7)";
          circle.style.backgroundColor = "rgba(99, 102, 241, 0.12)";

          safeSpaceBreathTimeout = setTimeout(run478, 8000);
        }, 7000);
      }, 4000);
    };
    run478();
  } else if (currentBreathPattern === 'sigh') {
    // Physiological Sigh (2s Inhale, 1s Top-up Inhale, 6s Slow Exhale)
    const runSigh = () => {
      text.innerText = tr({ de: "1. Tief Einatmen", en: "1. Deep Inhale", fr: "1. Inspirez", it: "1. Inspira a fondo", es: "1. Inhala profundo", el: "1. Βαθιά Εισπνοή" });
      if (countEl) countEl.innerText = "2s";
      circle.style.transform = "scale(1.25)";
      circle.style.borderColor = "rgba(20, 184, 166, 0.8)";

      safeSpaceBreathTimeout = setTimeout(() => {
        text.innerText = tr({ de: "2. Nochmal nachatmen!", en: "2. Top-up Inhale!", fr: "2. Complétez !", it: "2. Riempi ancora!", es: "2. ¡Inhala más!", el: "2. Συμπληρώστε!" });
        if (countEl) countEl.innerText = "1s";
        circle.style.transform = "scale(1.45)";
        circle.style.borderColor = "rgba(137, 207, 240, 0.9)";

        safeSpaceBreathTimeout = setTimeout(() => {
          text.innerText = tr({ de: "Langer beruhigender Seufzer...", en: "Long Calming Sigh...", fr: "Long soupir apaisant...", it: "Lungo sospiro calmante...", es: "Largo suspiro calmante...", el: "Μεγάλος αναστεναγμός..." });
          if (countEl) countEl.innerText = "6s";
          circle.style.transform = "scale(0.88)";
          circle.style.borderColor = "rgba(168, 85, 247, 0.8)";

          safeSpaceBreathTimeout = setTimeout(runSigh, 6000);
        }, 1200);
      }, 2000);
    };
    runSigh();
  } else {
    // 4-4-4 Box Breathing (Navy SEAL 4s Inhale, 4s Hold, 4s Exhale, 4s Hold)
    const run444 = () => {
      text.innerText = tr({ de: "Einatmen...", en: "Inhale...", fr: "Inspirez...", it: "Inspira...", es: "Inhala...", el: "Εισπνοή..." });
      if (countEl) countEl.innerText = "4s";
      circle.style.transform = "scale(1.35)";
      circle.style.borderColor = "rgba(20, 184, 166, 0.9)";
      circle.style.backgroundColor = "rgba(20, 184, 166, 0.15)";

      safeSpaceBreathTimeout = setTimeout(() => {
        text.innerText = tr({ de: "Anhalten...", en: "Hold...", fr: "Bloquez...", it: "Trattieni...", es: "Mantén...", el: "Κράτημα..." });
        if (countEl) countEl.innerText = "4s";
        circle.style.borderColor = "rgba(245, 158, 11, 0.8)";
        circle.style.backgroundColor = "rgba(245, 158, 11, 0.15)";

        safeSpaceBreathTimeout = setTimeout(() => {
          text.innerText = tr({ de: "Ausatmen...", en: "Exhale...", fr: "Expirez...", it: "Espira...", es: "Exhala...", el: "Εκπνοή..." });
          if (countEl) countEl.innerText = "4s";
          circle.style.transform = "scale(0.92)";
          circle.style.borderColor = "rgba(20, 184, 166, 0.5)";
          circle.style.backgroundColor = "rgba(20, 184, 166, 0.05)";

          safeSpaceBreathTimeout = setTimeout(() => {
            text.innerText = tr({ de: "Leer Anhalten...", en: "Hold Empty...", fr: "Poumons vides...", it: "Pausa a vuoto...", es: "Pausa vacío...", el: "Κενό κράτημα..." });
            if (countEl) countEl.innerText = "4s";
            circle.style.borderColor = "rgba(99, 102, 241, 0.7)";

            safeSpaceBreathTimeout = setTimeout(run444, 4000);
          }, 4000);
        }, 4000);
      }, 4000);
    };
    run444();
  }
}
window.startSafeSpaceBreathCycle = startSafeSpaceBreathCycle;

function stopSafeSpaceBreathCycle() {
  if (safeSpaceBreathTimeout) {
    clearTimeout(safeSpaceBreathTimeout);
    safeSpaceBreathTimeout = null;
  }
}
window.stopSafeSpaceBreathCycle = stopSafeSpaceBreathCycle;

function resetEyeRestUI() {
  eyeRestSeconds = 20;
  eyeRestRunning = false;
  const timeEl = document.getElementById('safespace-eyes-time');
  const btn = document.getElementById('safespace-eyes-btn');
  if (timeEl) timeEl.innerText = '20s';
  if (btn) btn.innerHTML = `<i data-lucide="play" class="w-4 h-4"></i> <span>20s Augen-Timer starten</span>`;
  if (typeof renderLucideIcons === 'function') renderLucideIcons();
}
window.resetEyeRestUI = resetEyeRestUI;

function toggleEyeRestTimer() {
  if (eyeRestRunning) {
    stopEyeRestTimer();
  } else {
    startEyeRestTimer();
  }
}
window.toggleEyeRestTimer = toggleEyeRestTimer;

function startEyeRestTimer() {
  stopEyeRestTimer();
  eyeRestRunning = true;
  eyeRestSeconds = 20;
  const timeEl = document.getElementById('safespace-eyes-time');
  const btn = document.getElementById('safespace-eyes-btn');
  if (btn) btn.innerHTML = `<i data-lucide="pause" class="w-4 h-4"></i> <span>Timer pausieren</span>`;
  if (typeof renderLucideIcons === 'function') renderLucideIcons();

  eyeRestTimerInterval = setInterval(() => {
    eyeRestSeconds--;
    if (timeEl) timeEl.innerText = `${eyeRestSeconds}s`;
    if (eyeRestSeconds <= 0) {
      stopEyeRestTimer();
      if (typeof playProceduralSound === 'function') playProceduralSound(2);
      showToast(tr({
        de: "👀 Augen entspannt! Wunderbar erholt.",
        en: "👀 Eyes relaxed! Wonderful recharge.",
        fr: "👀 Yeux reposés ! Recharge réussie.",
        it: "👀 Occhi rilassati! Ottima ricarica.",
        es: "👀 ¡Ojos descansados! Recarga completada.",
        el: "👀 Τα μάτια ξεκουράστηκαν! Υπέροχη ανανέωση."
      }));
      resetEyeRestUI();
    }
  }, 1000);
}
window.startEyeRestTimer = startEyeRestTimer;

function stopEyeRestTimer() {
  if (eyeRestTimerInterval) {
    clearInterval(eyeRestTimerInterval);
    eyeRestTimerInterval = null;
  }
  eyeRestRunning = false;
}
window.stopEyeRestTimer = stopEyeRestTimer;

function startDopamineDetoxTimer(sec = 60) {
  openSafeSpaceModal();
  switchSafeSpaceTab('anchor');
  showToast(tr({
    de: "⏳ 60s Reizstille gestartet. Schließe die Augen und lass die Gedanken ziehen.",
    en: "⏳ 60s Sensory silence started. Close your eyes and let your mind wander.",
    fr: "⏳ 60s de calme sensoriel démarrées.",
    it: "⏳ 60s di silenzio sensoriale avviati.",
    es: "⏳ 60s de silencio sensorial iniciados.",
    el: "⏳ 60 δευτ. αισθητηριακής ηρεμίας ξεκίνησαν."
  }));
}
window.startDopamineDetoxTimer = startDopamineDetoxTimer;

function quickPlaySoundscape(type) {
  if (typeof playAmbientSound === 'function') {
    playAmbientSound(type, true);
    showToast(tr({
      de: `🎧 Soundscape "${type}" aktiviert`,
      en: `🎧 Soundscape "${type}" active`,
      fr: `🎧 Ambiance "${type}" activée`,
      it: `🎧 Soundscape "${type}" attivo`,
      es: `🎧 Sonido "${type}" activado`,
      el: `🎧 Ήχος "${type}" ενεργοποιήθηκε`
    }));
  }
}
window.quickPlaySoundscape = quickPlaySoundscape;

function toggleSafeSpaceNoise() {
  safeSpaceNoiseActive = !safeSpaceNoiseActive;
  const btn = document.getElementById('safespace-noise-btn');
  if (!btn) return;
  if (safeSpaceNoiseActive) {
    btn.innerText = currentLang === 'de' ? "Bach-Sound aus" : "Stop Stream Sound";
    btn.className = "px-3.5 py-1.5 bg-red-500/20 hover:bg-red-500/30 border border-red-500/30 text-red-300 text-xs font-bold rounded-lg transition";
    if (typeof playAmbientSound === 'function') {
      playAmbientSound('stream', true);
    }
  } else {
    btn.innerText = currentLang === 'de' ? "Bach-Sound ein" : "Start Stream Sound";
    btn.className = "px-3.5 py-1.5 bg-teal-500/20 hover:bg-teal-500/30 border border-teal-500/30 text-teal-300 text-xs font-bold rounded-lg transition";
    if (typeof stopAmbientSound === 'function') {
      stopAmbientSound(true);
    }
  }
}
window.toggleSafeSpaceNoise = toggleSafeSpaceNoise;

function resetAnchorSteps() {
  anchorStep = 1;
  updateAnchorStepUI();
}

function nextAnchorStep() {
  anchorStep++;
  if (anchorStep > 5) {
    showToast(currentLang === 'de' ? "Erdung erfolgreich abgeschlossen! 🧘‍♂️" : "Grounding completed successfully! 🧘‍♂️");
    closeSafeSpaceModal();
  } else {
    updateAnchorStepUI();
    if (typeof playProceduralSound === 'function') {
      playProceduralSound(3);
    }
  }
}

function updateAnchorStepUI() {
  const titleEl = document.getElementById('anchor-step-title');
  const textEl = document.getElementById('anchor-step-instruction');
  const progressEl = document.getElementById('anchor-progress-bar');
  if (!titleEl || !textEl || !progressEl) return;
  const steps = ANCHOR_STEPS[currentLang] || ANCHOR_STEPS.de;
  const stepData = steps[anchorStep - 1] || steps[0];
  titleEl.innerText = stepData.title;
  textEl.innerText = stepData.text;
  progressEl.style.width = `${anchorStep * 20}%`;
}

// ===== HEADER LAYOUT CUSTOMIZER =====
function setHeaderLayout(mode) {
  const validModes = ['smart_hubs', 'minimal', 'classic'];
  if (!validModes.includes(mode)) mode = 'smart_hubs';
  
  if (typeof localStorage !== 'undefined') {
    localStorage.setItem('noodle_header_layout', mode);
  }

  // 1. Center Flank Buttons (Was nun? is preserved; Fokus is integrated)
  const whatnowBtn = document.getElementById('btn-whatnow-dance');
  const focusBtn = document.getElementById('btn-focus-mode');
  if (whatnowBtn) whatnowBtn.classList.remove('hidden');
  if (focusBtn) focusBtn.classList.add('hidden');

  // 2. Wellbeing & Options (Optionen MUSS in jedem Modus sichtbar sein!)
  const wellbeingCapsule = document.getElementById('header-capsule-wellbeing');
  const reportContainer = document.getElementById('header-btn-report-container');
  const optionsContainer = document.getElementById('header-btn-options-container');

  if (wellbeingCapsule) wellbeingCapsule.classList.remove('hidden');
  if (optionsContainer) optionsContainer.classList.remove('hidden');

  if (reportContainer) {
    if (mode === 'minimal') reportContainer.classList.add('hidden');
    else reportContainer.classList.remove('hidden');
  }

  // 3. Update UI Buttons in Settings Dropdown
  const modes = ['smart_hubs', 'minimal', 'classic'];
  modes.forEach(m => {
    const btn = document.getElementById(`btn-layout-${m}`);
    if (btn) {
      if (m === mode) {
        btn.className = 'py-1 px-1.5 rounded-xl transition text-center bg-purple-500/20 text-purple-200 border border-purple-500/40 cursor-pointer font-bold shadow-sm';
      } else {
        btn.className = 'py-1 px-1.5 rounded-xl transition text-center text-gray-400 hover:text-white cursor-pointer';
      }
    }
  });

  if (typeof lucide !== 'undefined') lucide.createIcons();
}
window.setHeaderLayout = setHeaderLayout;

function initHeaderLayout() {
  if (typeof localStorage === 'undefined') return;
  const saved = localStorage.getItem('noodle_header_layout') || 'classic';
  setHeaderLayout(saved);
}
window.initHeaderLayout = initHeaderLayout;

function toggleAllThemesDropdown() {
  const extPanel = document.getElementById('panel-themes-extended');
  const icon = document.getElementById('theme-expand-icon');
  const label = document.getElementById('theme-expand-label');
  if (!extPanel) return;
  const isHidden = extPanel.classList.contains('hidden');
  if (isHidden) {
    extPanel.classList.remove('hidden');
    extPanel.classList.add('grid');
    if (icon) icon.classList.add('rotate-180');
    if (label) label.textContent = (typeof tr === 'function') ? tr({ de: 'Weniger', en: 'Less', fr: 'Moins', it: 'Meno', es: 'Menos', el: 'Λιγότερα' }) : 'Weniger';
  } else {
    extPanel.classList.add('hidden');
    extPanel.classList.remove('grid');
    if (icon) icon.classList.remove('rotate-180');
    if (label) label.textContent = (typeof tr === 'function') ? tr({ de: 'Alle (16)', en: 'All (16)', fr: 'Tous (16)', it: 'Tutti (16)', es: 'Todos (16)', el: 'Όλα (16)' }) : 'Alle (16)';
  }
  if (typeof renderLucideIcons === 'function') renderLucideIcons();
  else if (typeof lucide !== 'undefined' && typeof lucide.createIcons === 'function') lucide.createIcons();
}
window.toggleAllThemesDropdown = toggleAllThemesDropdown;

if (typeof document !== 'undefined') {
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initHeaderLayout);
  } else {
    initHeaderLayout();
  }
}



/* --- audio-core.js --- */

// =========================================================================
// MULTI-TRACK AMBIENT MIXER & BINAURAL FOCUS FREQUENCIES ENGINE
// =========================================================================

var activeAmbientLayers = {}; // [type]: { source, gainNode, filter, volume }
var activeBinauralBeat = null; // 'alpha', 'theta', 'gamma', or null
var binauralAudioNodes = null;
var binauralVolume = 0.4;

const SOUND_MIX_PRESETS = {
  rainy_cafe: {
    name: 'Regnerisches Café',
    icon: '☕',
    layers: { cafe: 0.65, stream: 0.5 }
  },
  camp_forest: {
    name: 'Wald & Lagerfeuer',
    icon: '🏕️',
    layers: { campfire: 0.7, birds: 0.4, breeze: 0.35 }
  },
  zen_deep: {
    name: 'Zen Deep Space',
    icon: '🧘',
    layers: { space: 0.65, breeze: 0.3 }
  },
  study_cozy: {
    name: 'Cozy Study Corner',
    icon: '📚',
    layers: { cafe: 0.45, campfire: 0.4, breeze: 0.25 }
  }
};

function isAmbientLayerActive(type) {
  return Boolean(activeAmbientLayers[type]);
}

function getAmbientLayerVolume(type) {
  return activeAmbientLayers[type] ? (activeAmbientLayers[type].volume || 0.5) : 0.5;
}

function setAmbientLayerVolume(type, vol) {
  const v = Math.max(0, Math.min(1, parseFloat(vol)));
  if (activeAmbientLayers[type]) {
    activeAmbientLayers[type].volume = v;
    if (activeAmbientLayers[type].gainNode && audioCtx) {
      const now = audioCtx.currentTime;
      activeAmbientLayers[type].gainNode.gain.cancelScheduledValues(now);
      activeAmbientLayers[type].gainNode.gain.linearRampToValueAtTime(v * (soundMasterVolume || 0.5), now + 0.05);
    }
  }
  updateMixerUI();
}

function toggleAmbientLayer(type, forceState) {
  initAudioContext();
  if (!audioCtx) return;

  const isRunning = Boolean(activeAmbientLayers[type]);
  const shouldRun = forceState !== undefined ? forceState : !isRunning;

  if (!shouldRun && isRunning) {
    stopAmbientLayer(type);
  } else if (shouldRun && !isRunning) {
    startAmbientLayer(type);
  }
  updateMixerUI();
}

function startAmbientLayer(type, initialVolume = 0.5) {
  initAudioContext();
  if (!audioCtx) return;
  if (activeAmbientLayers[type]) return; // already active

  const masterDest = getMasterAudioDestination() || audioCtx.destination;
  const layerGain = audioCtx.createGain();
  const vol = Math.max(0, Math.min(1, initialVolume));
  layerGain.gain.setValueAtTime(vol * (soundMasterVolume || 0.5), audioCtx.currentTime);
  layerGain.connect(masterDest);

  const layerObj = {
    type: type,
    gainNode: layerGain,
    volume: vol,
    nodes: []
  };

  const now = audioCtx.currentTime;

  if (type === 'cafe') {
    const source = audioCtx.createBufferSource();
    source.buffer = getNoiseBuffer('pink');
    source.loop = true;
    const filter = audioCtx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(280, now);
    source.connect(filter);
    filter.connect(layerGain);
    source.start(now);
    layerObj.nodes.push(source, filter);
  } else if (type === 'stream') {
    const source = audioCtx.createBufferSource();
    source.buffer = getNoiseBuffer('pink');
    source.loop = true;
    const filter = audioCtx.createBiquadFilter();
    filter.type = 'bandpass';
    filter.frequency.setValueAtTime(800, now);
    filter.Q.setValueAtTime(1.2, now);
    source.connect(filter);
    filter.connect(layerGain);
    source.start(now);
    layerObj.nodes.push(source, filter);
  } else if (type === 'campfire') {
    const source = audioCtx.createBufferSource();
    source.buffer = getNoiseBuffer('brown');
    source.loop = true;
    const filter = audioCtx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(140, now);
    source.connect(filter);
    filter.connect(layerGain);
    source.start(now);
    layerObj.nodes.push(source, filter);
  } else if (type === 'birds') {
    const source = audioCtx.createBufferSource();
    source.buffer = getNoiseBuffer('pink');
    source.loop = true;
    const filter = audioCtx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(320, now);
    source.connect(filter);
    filter.connect(layerGain);
    source.start(now);
    layerObj.nodes.push(source, filter);
  } else if (type === 'breeze') {
    const source = audioCtx.createBufferSource();
    source.buffer = getNoiseBuffer('pink');
    source.loop = true;
    const filter = audioCtx.createBiquadFilter();
    filter.type = 'bandpass';
    filter.frequency.setValueAtTime(320, now);
    source.connect(filter);
    filter.connect(layerGain);
    source.start(now);
    layerObj.nodes.push(source, filter);
  } else if (type === 'space') {
    const freqs = [65.4, 98.0, 130.8];
    const filter = audioCtx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(260, now);
    filter.connect(layerGain);
    freqs.forEach(f => {
      const osc = audioCtx.createOscillator();
      const oscGain = audioCtx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(f, now);
      oscGain.gain.setValueAtTime(0.12 / freqs.length, now);
      osc.connect(oscGain);
      oscGain.connect(filter);
      osc.start(now);
      layerObj.nodes.push(osc, oscGain);
    });
    layerObj.nodes.push(filter);
  }

  activeAmbientLayers[type] = layerObj;
  updateMixerUI();
}

function stopAmbientLayer(type) {
  if (!activeAmbientLayers[type]) return;
  const layer = activeAmbientLayers[type];
  if (layer.gainNode && audioCtx) {
    try {
      layer.gainNode.gain.cancelScheduledValues(audioCtx.currentTime);
      layer.gainNode.gain.linearRampToValueAtTime(0.0001, audioCtx.currentTime + 0.15);
    } catch (e) {}
  }
  setTimeout(() => {
    (layer.nodes || []).forEach(node => {
      try { if (node.stop) node.stop(); } catch (e) {}
      try { if (node.disconnect) node.disconnect(); } catch (e) {}
    });
    try { if (layer.gainNode) layer.gainNode.disconnect(); } catch (e) {}
  }, 180);
  delete activeAmbientLayers[type];
  updateMixerUI();
}

function stopAllAmbientLayers() {
  Object.keys(activeAmbientLayers).forEach(stopAmbientLayer);
  stopBinauralBeat();
  updateMixerUI();
}

function applySoundMixPreset(presetKey) {
  const preset = SOUND_MIX_PRESETS[presetKey];
  if (!preset) return;

  stopAllAmbientLayers();
  setTimeout(() => {
    Object.entries(preset.layers).forEach(([type, vol]) => {
      startAmbientLayer(type, vol);
    });
    if (typeof showToast === 'function') {
      showToast(`🎛️ Mix-Preset aktiv: ${preset.name}`);
    }
    updateMixerUI();
  }, 200);
}

// =========================================================================
// BINAURAL FOCUS FREQUENCIES (ALPHA, THETA, GAMMA)
// =========================================================================

function toggleBinauralBeat(type) {
  if (activeBinauralBeat === type) {
    stopBinauralBeat();
  } else {
    playBinauralBeat(type);
  }
}

function playBinauralBeat(type) {
  initAudioContext();
  if (!audioCtx) return;

  stopBinauralBeat();

  let baseFreq = 200;
  let beatDiff = 10; // Alpha 10 Hz (8-12 Hz)
  let label = 'Alpha (10 Hz) · Flow & Entspannung';

  if (type === 'theta') {
    baseFreq = 150;
    beatDiff = 6; // Theta 6 Hz (4-7 Hz)
    label = 'Theta (6 Hz) · Tiefenmeditation & Intuition';
  } else if (type === 'gamma') {
    baseFreq = 240;
    beatDiff = 40; // Gamma 40 Hz (30-50 Hz)
    label = 'Gamma (40 Hz) · Spitzen-Fokus & Kognition';
  }

  const now = audioCtx.currentTime;
  const masterGain = audioCtx.createGain();
  masterGain.gain.setValueAtTime(0.001, now);
  masterGain.gain.linearRampToValueAtTime(binauralVolume * (soundMasterVolume || 0.5) * 0.4, now + 1.2);
  masterGain.connect(getMasterAudioDestination() || audioCtx.destination);

  // Left channel
  const oscL = audioCtx.createOscillator();
  const panL = audioCtx.createStereoPanner ? audioCtx.createStereoPanner() : null;
  oscL.type = 'sine';
  oscL.frequency.setValueAtTime(baseFreq, now);

  // Right channel
  const oscR = audioCtx.createOscillator();
  const panR = audioCtx.createStereoPanner ? audioCtx.createStereoPanner() : null;
  oscR.type = 'sine';
  oscR.frequency.setValueAtTime(baseFreq + beatDiff, now);

  if (panL && panR) {
    panL.pan.setValueAtTime(-1.0, now);
    panR.pan.setValueAtTime(1.0, now);
    oscL.connect(panL);
    panL.connect(masterGain);
    oscR.connect(panR);
    panR.connect(masterGain);
  } else {
    oscL.connect(masterGain);
    oscR.connect(masterGain);
  }

  oscL.start(now);
  oscR.start(now);

  activeBinauralBeat = type;
  binauralAudioNodes = { oscL, oscR, panL, panR, masterGain };

  if (typeof showToast === 'function') {
    showToast(`🧠 Binaurale Frequenz: ${label}`);
  }
  updateMixerUI();
}

function stopBinauralBeat() {
  if (binauralAudioNodes && audioCtx) {
    try {
      const now = audioCtx.currentTime;
      binauralAudioNodes.masterGain.gain.cancelScheduledValues(now);
      binauralAudioNodes.masterGain.gain.linearRampToValueAtTime(0.0001, now + 0.3);
      setTimeout(() => {
        try { if (binauralAudioNodes.oscL) binauralAudioNodes.oscL.stop(); } catch (e) {}
        try { if (binauralAudioNodes.oscR) binauralAudioNodes.oscR.stop(); } catch (e) {}
        try { if (binauralAudioNodes.masterGain) binauralAudioNodes.masterGain.disconnect(); } catch (e) {}
        binauralAudioNodes = null;
      }, 350);
    } catch (e) {}
  }
  activeBinauralBeat = null;
  updateMixerUI();
}

function setBinauralVolume(vol) {
  binauralVolume = Math.max(0, Math.min(1, parseFloat(vol)));
  if (binauralAudioNodes && audioCtx) {
    const now = audioCtx.currentTime;
    binauralAudioNodes.masterGain.gain.cancelScheduledValues(now);
    binauralAudioNodes.masterGain.gain.linearRampToValueAtTime(binauralVolume * (soundMasterVolume || 0.5) * 0.4, now + 0.05);
  }
}

function updateMixerUI() {
  const mixerLayers = ['cafe', 'stream', 'campfire', 'birds', 'breeze', 'space'];
  mixerLayers.forEach(layer => {
    const active = isAmbientLayerActive(layer);
    const vol = getAmbientLayerVolume(layer);

    const btn = document.getElementById(`mixer-toggle-${layer}`);
    const slider = document.getElementById(`mixer-vol-${layer}`);
    const valBadge = document.getElementById(`mixer-val-${layer}`);

    if (btn) {
      if (active) {
        btn.className = 'px-2.5 py-1 rounded-xl text-xs font-bold bg-fuchsia-500/25 text-fuchsia-200 border border-fuchsia-400/60 shadow-sm flex items-center gap-1.5 cursor-pointer';
      } else {
        btn.className = 'px-2.5 py-1 rounded-xl text-xs font-semibold text-gray-400 hover:text-white bg-white/5 border border-white/10 flex items-center gap-1.5 cursor-pointer';
      }
    }
    if (slider) {
      slider.value = vol;
      slider.disabled = !active;
      slider.style.opacity = active ? '1' : '0.4';
    }
    if (valBadge) {
      valBadge.innerText = `${Math.round(vol * 100)}%`;
      valBadge.style.opacity = active ? '1' : '0.4';
    }
  });

  // Binaural UI
  ['alpha', 'theta', 'gamma'].forEach(b => {
    const btn = document.getElementById(`binaural-btn-${b}`);
    if (btn) {
      if (activeBinauralBeat === b) {
        btn.className = 'flex-1 py-1.5 px-2 rounded-xl font-bold text-xs bg-fuchsia-500 text-black shadow-lg shadow-fuchsia-500/30 transition flex items-center justify-center gap-1 cursor-pointer animate-pulse';
      } else {
        btn.className = 'flex-1 py-1.5 px-2 rounded-xl font-semibold text-xs text-gray-300 hover:text-white bg-white/5 hover:bg-white/10 border border-white/10 transition flex items-center justify-center gap-1 cursor-pointer';
      }
    }
  });

  const binLiveBadge = document.getElementById('binaural-live-indicator');
  if (binLiveBadge) {
    binLiveBadge.classList.toggle('hidden', !activeBinauralBeat);
  }

  updateAudioStudioHeader();
  updateHeaderSoundBtnUI();
}

// Globale Audio-Variablen
var audioCtx = null;
var currentSoundType = null;
var soundGainNode = null;
var soundOscillators = [];
var soundMasterVolume = 0.5;
var activeUserAudio = null; // Speichert das aktive HTML5-Audio-Objekt
var localSoundCache = {}; 
var activeNodes = [];
var activeTimeouts = [];
var noiseBuffers = {};
var pendingCrossfadeNodes = [];
var pendingCrossfadeGains = [];

// Playlist-Zustände für eigene Tracks
var DEFAULT_PRELOADED_TRACKS = [
  { id: 'track_lofi', name: '☕ Deep Focus Lofi', url: 'music/deep_focus_lofi.mp3', bpm: 85, presetKey: 'lofi_chill', duration: 180, isPreloaded: true },
  { id: 'track_deep_house', name: '🪩 Deep House Sunset', url: 'music/deep_house_sunset.mp3', bpm: 126, presetKey: 'deep_house', duration: 210, isPreloaded: true },
  { id: 'track_synthwave', name: '🌆 Synthwave Neon Drive', url: 'music/synthwave_neon_drive.mp3', bpm: 128, presetKey: 'cyber_wave', duration: 195, isPreloaded: true },
  { id: 'track_zen', name: '🍃 Zen Meditation Flow', url: 'music/zen_meditation_flow.mp3', bpm: 118, presetKey: 'ambient_flow', duration: 240, isPreloaded: true }
];
var playlistTracks = [...DEFAULT_PRELOADED_TRACKS];
var currentTrackIndex = 0;
var isPlayerShuffleEnabled = true; // standardmäßig aktiv (zufällige Wiedergabe)
var playerRepeatMode = 'all'; // 'off' | 'all' | 'one'
var isPlayerMuted = false;
var volumeBeforeMute = 0.5;
var draggedTrackIndex = null;
var masterGainNode = null;

function getMasterAudioDestination() {
  initAudioContext();
  if (!audioCtx) return null;
  if (!masterGainNode) {
    masterGainNode = audioCtx.createGain();
    masterGainNode.gain.setValueAtTime(1.0, audioCtx.currentTime);
    masterGainNode.connect(audioCtx.destination);
  }
  return masterGainNode;
}
window.getMasterAudioDestination = getMasterAudioDestination;

function initAudioContext() {
  try {
    if (!audioCtx || audioCtx.state === 'closed') {
      const AudioContextClass = window.AudioContext || window.webkitAudioContext;
      if (AudioContextClass) {
        audioCtx = new AudioContextClass();
      }
    }
    if (audioCtx && audioCtx.state === 'suspended') {
      audioCtx.resume().catch(() => {});
    }
    if (audioCtx && !masterGainNode) {
      masterGainNode = audioCtx.createGain();
      masterGainNode.gain.setValueAtTime(1.0, audioCtx.currentTime);
      masterGainNode.connect(audioCtx.destination);
    }
  } catch (e) {
    console.warn("AudioContext init warning:", e);
  }
}

// Mobiler Audio-Unlock für iOS Safari & Android beim ersten Benutzerkontakt
if (typeof window !== 'undefined' && typeof window.addEventListener === 'function') {
  const unlockMobileAudio = () => {
    initAudioContext();
    if (typeof window.removeEventListener === 'function') {
      window.removeEventListener('touchstart', unlockMobileAudio);
      window.removeEventListener('touchend', unlockMobileAudio);
      window.removeEventListener('pointerdown', unlockMobileAudio);
      window.removeEventListener('click', unlockMobileAudio);
    }
  };
  window.addEventListener('touchstart', unlockMobileAudio, { passive: true, once: true });
  window.addEventListener('touchend', unlockMobileAudio, { passive: true, once: true });
  window.addEventListener('pointerdown', unlockMobileAudio, { passive: true, once: true });
  window.addEventListener('click', unlockMobileAudio, { passive: true, once: true });

  // Nahtloses Reaktivieren beim Zurückkehren aus dem Hintergrund (iOS Safari & Android)
  if (typeof document !== 'undefined' && typeof document.addEventListener === 'function') {
    document.addEventListener('visibilitychange', () => {
      if (document.visibilityState === 'visible' && audioCtx && audioCtx.state === 'suspended' && (currentSoundType || (activeUserAudio && !activeUserAudio.paused))) {
        audioCtx.resume().catch(() => {});
      }
    });
  }
}

// Hilfsfunktion: Erzeugt lückenlose Rausch-Loops im Arbeitsspeicher
function getNoiseBuffer(type) {
  initAudioContext();
  if (!audioCtx) return null;
  if (noiseBuffers[type]) return noiseBuffers[type];
  
  const sampleRate = audioCtx.sampleRate || 44100;
  const bufferSize = sampleRate * 4;
  const buffer = audioCtx.createBuffer(2, bufferSize, sampleRate);
  const left = buffer.getChannelData(0);
  const right = buffer.getChannelData(1);
  
  if (type === 'pink') {
    let b0_l=0, b1_l=0, b2_l=0, b3_l=0, b4_l=0, b5_l=0, b6_l=0;
    let b0_r=0, b1_r=0, b2_r=0, b3_r=0, b4_r=0, b5_r=0, b6_r=0;
    for (let i = 0; i < bufferSize; i++) {
      let white_l = Math.random() * 2 - 1;
      b0_l = 0.99886 * b0_l + white_l * 0.0555179;
      b1_l = 0.99332 * b1_l + white_l * 0.0750759;
      b2_l = 0.96900 * b2_l + white_l * 0.1538520;
      b3_l = 0.86650 * b3_l + white_l * 0.3104856;
      b4_l = 0.55000 * b4_l + white_l * 0.5329522;
      b5_l = -0.7616 * b5_l - white_l * 0.0168980;
      left[i] = (b0_l + b1_l + b2_l + b3_l + b4_l + b5_l + b6_l + white_l * 0.5362) * 0.11;
      b6_l = white_l * 0.115926;
      
      let white_r = Math.random() * 2 - 1;
      b0_r = 0.99886 * b0_r + white_r * 0.0555179;
      b1_r = 0.99332 * b1_r + white_r * 0.0750759;
      b2_r = 0.96900 * b2_r + white_r * 0.1538520;
      b3_r = 0.86650 * b3_r + white_r * 0.3104856;
      b4_r = 0.55000 * b4_r + white_r * 0.5329522;
      b5_r = -0.7616 * b5_r - white_r * 0.0168980;
      right[i] = (b0_r + b1_r + b2_r + b3_r + b4_r + b5_r + b6_r + white_r * 0.5362) * 0.11;
      b6_r = white_r * 0.115926;
    }
  } else if (type === 'brown') {
    let lastOut_l = 0.0, lastOut_r = 0.0;
    for (let i = 0; i < bufferSize; i++) {
      let white_l = Math.random() * 2 - 1;
      left[i] = (lastOut_l + (0.02 * white_l)) / 1.02;
      lastOut_l = left[i];
      left[i] *= 3.5;
      
      let white_r = Math.random() * 2 - 1;
      right[i] = (lastOut_r + (0.02 * white_r)) / 1.02;
      lastOut_r = right[i];
      right[i] *= 3.5;
    }
  }
  noiseBuffers[type] = buffer;
  return buffer;
}

function clearActiveTimeouts() {
  activeTimeouts.forEach(clearTimeout);
  activeTimeouts = [];
}

// Hauptfunktion zum Abspielen der 18 Naturgeräusche (mit integriertem Crossfade-Support & Toggle-Stopp)
function playAmbientSound(type, crossfade = false) {
  initAudioContext();
  if (!audioCtx) return;

  // Wenn der geklickte Sound bereits läuft -> stoppen (Toggle-Funktion)
  if (currentSoundType === type) {
    stopAmbientSound(true);
    if (typeof stopAllStudioAudio === 'function') stopAllStudioAudio();
    updateSoundscapeUI();
    if (typeof showToast === 'function') {
      showToast(typeof tr === 'function' ? tr({ de: 'Audio gestoppt ⏹️', en: 'Audio stopped ⏹️' }) : 'Audio gestoppt ⏹️');
    }
    return;
  }

  // Ansonsten: Alle anderen vorher laufenden Sounds/Musik/Radio restlos stoppen
  if (typeof stopAllStudioAudio === 'function') stopAllStudioAudio();
  stopAmbientSound(true);

  // Exklusivität: Radio stoppen falls aktiv
  try {
    if (typeof RadioNewsEngine !== 'undefined' && typeof RadioNewsEngine.toggleRadioPlayback === 'function' && window.isRadioPlaying) {
      RadioNewsEngine.toggleRadioPlayback();
    } else if (typeof window !== 'undefined' && window.radioAudioEl && !window.radioAudioEl.paused) {
      window.radioAudioEl.pause();
    }
  } catch (e) {}

  currentSoundType = type;
  soundGainNode = audioCtx.createGain();
  soundGainNode.gain.setValueAtTime(soundMasterVolume * 1.0, audioCtx.currentTime);
  soundGainNode.connect(getMasterAudioDestination() || audioCtx.destination);

  // Generatoren anstoßen
  startAmbientGeneratorForType(type);

  updateSoundscapeUI();
  lastSelectedSound = type;
}

// Harmonisches Audio-Ducking für Sprachansagen
function duckAmbientVolume(ratio = 0.18) {
  if (soundGainNode && audioCtx) {
    try {
      const now = audioCtx.currentTime;
      soundGainNode.gain.cancelScheduledValues(now);
      soundGainNode.gain.setValueAtTime(soundGainNode.gain.value, now);
      soundGainNode.gain.linearRampToValueAtTime(soundMasterVolume * ratio, now + 0.2);
    } catch (e) {
      console.warn('[Audio] duckAmbientVolume error:', e);
    }
  }
  if (activeUserAudio) {
    try { activeUserAudio.volume = Math.max(0, Math.min(1, soundMasterVolume * ratio)); } catch (e) { console.warn('[Audio] duck activeUserAudio error:', e); }
  }
}

function restoreAmbientVolume() {
  if (soundGainNode && audioCtx) {
    try {
      const now = audioCtx.currentTime;
      soundGainNode.gain.cancelScheduledValues(now);
      soundGainNode.gain.setValueAtTime(soundGainNode.gain.value, now);
      soundGainNode.gain.linearRampToValueAtTime(soundMasterVolume * 1.0, now + 0.45);
    } catch (e) {
      console.warn('[Audio] restoreAmbientVolume error:', e);
    }
  }
  if (activeUserAudio) {
    try { activeUserAudio.volume = Math.max(0, Math.min(1, soundMasterVolume * 0.7)); } catch (e) { console.warn('[Audio] restore activeUserAudio error:', e); }
  }
}

// Sanfter, gleitender Lautstärke-Fade-Out am Sitzungsende
function fadeOutAmbientSound(durationSeconds = 4.5) {
  if (soundGainNode && audioCtx) {
    try {
      const now = audioCtx.currentTime;
      soundGainNode.gain.setValueAtTime(soundGainNode.gain.value, now);
      soundGainNode.gain.linearRampToValueAtTime(0.0001, now + durationSeconds);
    } catch (e) {
      console.warn('[Audio] Fade-Out Fehler:', e);
    }
  }
  if (activeUserAudio) {
    let steps = 25;
    let stepTime = (durationSeconds * 1000) / steps;
    let currentVol = activeUserAudio.volume;
    let volStep = currentVol / steps;
    let fadeInterval = setInterval(() => {
      if (activeUserAudio && activeUserAudio.volume > volStep) {
        activeUserAudio.volume -= volStep;
      } else {
        clearInterval(fadeInterval);
        try { if (activeUserAudio) activeUserAudio.pause(); } catch (e) { console.warn('[Audio] fadeOut activeUserAudio.pause error:', e); }
      }
    }, stepTime);
  }
  
  setTimeout(() => {
    stopAmbientSound(true); 
  }, durationSeconds * 1000 + 100);
}

// Fröhliche Dur-Erfolgs-Jingles (C-Dur / F-Dur / G-Dur Arpeggios mit glockenreinem Kalimba- / Marimba-Charakter)
function playCheerfulSuccessJingle() {
  initAudioContext();
  if (!audioCtx || isPlayerMuted) return;
  try {
    const now = audioCtx.currentTime;
    // Harmonische Dur-Akkordfolgen zur Auswahl
    const chordProgressions = [
      [523.25, 659.25, 783.99, 1046.50], // C5, E5, G5, C6 (C-Dur)
      [587.33, 739.99, 880.00, 1174.66], // D5, F#5, A5, D6 (D-Dur)
      [698.46, 880.00, 1046.50, 1396.91], // F5, A5, C6, F6 (F-Dur)
      [783.99, 987.77, 1174.66, 1567.98]  // G5, B5, D6, G6 (G-Dur)
    ];
    const notes = chordProgressions[Math.floor(Math.random() * chordProgressions.length)];
    
    notes.forEach((freq, i) => {
      const startTime = now + (i * 0.065);
      const osc = audioCtx.createOscillator();
      const gain = audioCtx.createGain();
      
      osc.type = i % 2 === 0 ? 'sine' : 'triangle';
      osc.frequency.setValueAtTime(freq, startTime);
      
      const vol = 0.22 * (soundMasterVolume || 0.5);
      gain.gain.setValueAtTime(0.0001, startTime);
      gain.gain.linearRampToValueAtTime(vol, startTime + 0.015);
      gain.gain.exponentialRampToValueAtTime(0.0001, startTime + 0.45);
      
      osc.connect(gain);
      gain.connect(audioCtx.destination);
      
      osc.start(startTime);
      osc.stop(startTime + 0.5);
      osc.onended = () => {
        try { osc.disconnect(); } catch (e) {}
        try { gain.disconnect(); } catch (e) {}
      };
    });
  } catch (e) {
    console.warn('[Audio] playCheerfulSuccessJingle warning:', e);
  }
}

